        if (node.nodeType === 3) {
          var text = node.nodeValue || "";
          for (var i = 0; i < text.length; i++) {
            chars.push({ c: text.charAt(i), bold: fctx.bold, italic: fctx.italic, underline: fctx.underline });
          }
          return;
