        if (node.nodeType !== 1) return;
        var tag = (node.tagName || "").toLowerCase();
        // Word emits <head><style>...</style></head> with mso-* and class
        // definitions — nothing we want in the text stream.
        if (tag === "head" || tag === "script" || tag === "style" || tag === "title") return;
        var sub = { bold: fctx.bold, italic: fctx.italic, underline: fctx.underline };
        if (tag === "b" || tag === "strong") sub.bold = true;
        if (tag === "i" || tag === "em")     sub.italic = true;
        if (tag === "u")                     sub.underline = true;
        var style = node.getAttribute && node.getAttribute("style");
        if (style) {
          // (?:^|[;\s]) anchor prevents matching "mso-bidi-font-weight"
          // (a Word property that doesn't reflect visual formatting).
          if (/(?:^|[;\s])font-weight\s*:\s*(bold|[6-9]\d{2})/i.test(style)) sub.bold = true;
          if (/(?:^|[;\s])font-style\s*:\s*italic/i.test(style))             sub.italic = true;
