  //     toggle modify mode without leaving the input area)
  //   • a dismiss × that hides the chip without losing the selection
  // The full document is ALWAYS sent as context — the selection just
  // tells the AI which clause to focus on (engine.js: CONTEXTUAL ANALYSIS
  // RULE).
  function setSelection(text) {
    var trimmed = String(text || "").trim();
    state.selectionText = trimmed;
    if (trimmed !== state.selectionLast) {
      state.selectionDismissed = false;
      state.selectionLast = trimmed;
    }
    if (!trimmed || trimmed.length < 4 || state.selectionDismissed) {
      selChipEl.hidden = true;
      selChipEl.innerHTML = "";
      if (state.rewrite) { state.rewrite = false; onModifyModeChange(_modifyMode()); }
      if (pillsEl) { pillsEl.hidden = true; pillsEl.innerHTML = ""; }
      _refreshPlaceholder();
      return;
    }
    selChipEl.hidden = false;
    var words = trimmed.split(/\s+/).length;
    var preview = trimmed.length > 80
      ? (trimmed.substring(0, 80).replace(/\S+$/, "").trim() + "…")
      : trimmed;
    selChipEl.innerHTML =
      '<span class="_eli3_chat_selchip_icon">📍</span>' +
      '<span class="_eli3_chat_selchip_label">Focus · ' + words + ' word' + (words === 1 ? "" : "s") + '</span>' +
      '<span class="_eli3_chat_selchip_preview" title="' + _esc(trimmed) + '">' + _esc(preview) + '</span>' +
      '<label class="_eli3_chat_selchip_rewrite">' +
        '<input type="checkbox" id="_eli3_chat_rewritechk"' + (state.rewrite ? " checked" : "") + '>' +
        '<span>Rewrite</span>' +
      '</label>' +
      '<button type="button" class="_eli3_chat_selchip_dismiss" title="Dismiss">×</button>';
    var dismissBtn = selChipEl.querySelector("._eli3_chat_selchip_dismiss");
    if (dismissBtn) dismissBtn.onclick = function () {
      state.selectionDismissed = true;
      selChipEl.hidden = true;
      if (pillsEl) { pillsEl.hidden = true; pillsEl.innerHTML = ""; }
      _refreshPlaceholder();
    };
    var rewriteChk = selChipEl.querySelector("#_eli3_chat_rewritechk");
    if (rewriteChk) rewriteChk.onchange = function () {
      state.rewrite = rewriteChk.checked;
      _refreshPlaceholder();
      _renderRewritePills();
      onModifyModeChange(_modifyMode());
    };
    _renderRewritePills();
    _refreshPlaceholder();
  }

  // Rewrite quick-prompt pills — shown only when Rewrite mode is checked
  // on a live selection. Each pill is a preset rewrite instruction; click
  // to auto-fill the input and submit. The user can still type a fully
  // custom prompt in the textarea — pills are accelerators, not the only
  // path. Tooltip on each pill shows the full prompt that will be sent.
  var _rewritePills = [
    { icon: "💎", label: "Polish",         prompt: "Polish this clause: tighten the language and improve readability without changing the substance." },
    { icon: "✂",  label: "Shorten",        prompt: "Make this clause more concise without losing any substantive obligations, protections, or carve-outs." },
    { icon: "📝", label: "Lengthen",       prompt: "Expand this clause with additional precision and supporting language. Cover edge cases that the original glosses over." },
    { icon: "⚖",  label: "Stronger for us", prompt: "Rewrite this clause to favor our side — narrower obligations on us, broader protections for us, longer cure periods, tighter carve-outs against us." },
    { icon: "🔄", label: "Plain English",  prompt: "Rewrite this clause in plain English while preserving its legal meaning exactly. No reduction in obligations or protections." },
  ];
  function _renderRewritePills() {
    if (!pillsEl) return;
    var should = state.rewrite && state.selectionText && !state.selectionDismissed;
    if (!should) {
      pillsEl.hidden = true;
      pillsEl.innerHTML = "";
      return;
    }
    pillsEl.hidden = false;
    // Show clause button appears alongside the pills when Rewrite is on.
    // Click → stage the selection in an action card with no AI call, so
    // the user can iterate by drag-selecting + regen chip without an
    // initial blanket rewrite. Wire is opt-in: if onShowClause isn't
    // provided, button is omitted entirely.
    var showBtn = onShowClause
      ? '<button type="button" class="_eli3_chat_rewrite_pill _eli3_chat_rewrite_pill_show" ' +
        'title="Show the selected clause as an editable preview — no AI call. Drag-select inside to regenerate portions.">' +
        '<span class="_eli3_chat_rewrite_pill_icon">📋</span>' +
        '<span class="_eli3_chat_rewrite_pill_label">Show clause</span>' +
      '</button>'
      : "";
    pillsEl.innerHTML = showBtn + _rewritePills.map(function (p, i) {
      return '<button type="button" class="_eli3_chat_rewrite_pill" data-i="' + i + '" ' +
        'title="' + _esc(p.prompt) + '">' +
        '<span class="_eli3_chat_rewrite_pill_icon">' + p.icon + '</span>' +
        '<span class="_eli3_chat_rewrite_pill_label">' + _esc(p.label) + '</span>' +
      '</button>';
    }).join("");
    var btns = pillsEl.querySelectorAll("._eli3_chat_rewrite_pill:not(._eli3_chat_rewrite_pill_show)");
    Array.prototype.forEach.call(btns, function (b) {
      b.onclick = function () {
        var i = parseInt(b.getAttribute("data-i"), 10);
        var p = _rewritePills[i];
        if (!p) return;
        inputEl.value = p.prompt;
        inputEl.focus();
        _doSend();
      };
    });
    var showBtnEl = pillsEl.querySelector("._eli3_chat_rewrite_pill_show");
    if (showBtnEl && onShowClause) {
      showBtnEl.onclick = function () {
        // Toggle behavior: if a staged card from this button is still
        // active (in DOM and not yet Apply/Reject'd), clicking again
        // removes it. Otherwise, spawn a fresh one. Done cards left in
        // chat history don't count as "active" — they stay as history.
        var existing = state.stagedCard;
        var isActive = existing
          && existing.parentNode
          && !existing.classList.contains("_eli3_chat_actioncard_done");
        if (isActive) {
          try { existing.parentNode.removeChild(existing); } catch (_e) {}
          state.stagedCard = null;
          return;
        }
        var sel = String(state.selectionText || "").trim();
        if (!sel) return;
        showBtnEl.disabled = true;
        showBtnEl.querySelector("._eli3_chat_rewrite_pill_label").textContent = "Loading…";
        Promise.resolve(onShowClause(sel))
          .then(function (card) {
            // Track the spawned card so the next click on Show toggles it.
            state.stagedCard = card || null;
          })
          .catch(function () { state.stagedCard = null; })
          .then(function () {
            showBtnEl.disabled = false;
            showBtnEl.querySelector("._eli3_chat_rewrite_pill_label").textContent = "Show clause";
          });
      };
    }
  }
  setSelection(initialSelection);

  // ─── Attach button + scope bar ───────────────────────────────────
  // Attach button: emoji + "Attach" word in the toolbar; turns into a
  // chip-with-✕ when an attachment is present so the user can detach
  // by clicking again.
  // Scope bar: visible only when an attachment is present. Three-way
  // segmented toggle (Live / Attached / Both) replaces the old two-state
  // bar. Default = "both" so the AI sees both contexts unless the user
  // narrows it.
  function setAttachment(att) {
    state.attachment = att || null;
    if (att) {
      attachBtn.classList.add("_eli3_chat_attach_on");
      var name = att.name || "attached";
      var truncName = name.length > 18 ? name.substring(0, 16) + "…" : name;
      attachBtn.innerHTML = '📎 <span class="_eli3_chat_attach_lbl">' + _esc(truncName) + '</span> <span class="_eli3_chat_attach_x">✕</span>';
      attachBtn.title = "Click to detach: " + name;
      scopeBarEl.hidden = false;
    } else {
      attachBtn.classList.remove("_eli3_chat_attach_on");
      attachBtn.innerHTML = '📎 <span class="_eli3_chat_attach_lbl">Attach</span>';
      attachBtn.title = "Attach file or template";
      scopeBarEl.hidden = true;
    }
  }
  function setScope(scope) {
    var s = String(scope || "");
    if (s !== "live" && s !== "attached" && s !== "both") s = "both";
    state.scope = s;
    Array.prototype.forEach.call(scopeBarEl.querySelectorAll("._eli3_chat_scopeseg"), function (seg) {
      var active = seg.getAttribute("data-scope") === state.scope;
      seg.classList.toggle("_eli3_chat_scopeseg_active", active);
    });
  }
  setAttachment(initialAttachment);
  setScope(initialScope);

  attachBtn.onclick = function () {
    if (state.attachment) onAttachClear();
    else onAttachOpen();
  };
  Array.prototype.forEach.call(scopeBarEl.querySelectorAll("._eli3_chat_scopeseg"), function (seg) {
    seg.onclick = function () {
      var s = seg.getAttribute("data-scope");
      setScope(s);
      onScopeChange(s);
    };
  });

  // ─── Draft toggle ────────────────────────────────────────────────
  draftChk.onchange = function () {
    state.draft = draftChk.checked;
    _refreshPlaceholder();
    onModifyModeChange(_modifyMode());
  };

  // ─── Improve button ──────────────────────────────────────────────
  improveBtn.onclick = function () {
    if (!onImprove) return;
    var current = String(inputEl.value || "").trim();
    if (!current) return;
    improveBtn.disabled = true;
    improveBtn.textContent = "⏳";
    Promise.resolve(onImprove(current)).then(function (improved) {
      improveBtn.textContent = "✨";
      improveBtn.disabled = false;
      if (improved) inputEl.value = improved;
    }).catch(function () {
      improveBtn.textContent = "✨";
      improveBtn.disabled = false;
    });
  };

  // ─── Send ────────────────────────────────────────────────────────
  function _doSend() {
    if (state.inFlight) return;
    var question = String(inputEl.value || "").trim();
    if (!question) return;
    // Asking a new question leaves edit mode (pins return, answers lock).
    if (editMode) _applyEditMode(false);
    state.inFlight = true;
    inputEl.value = "";
    inputEl.style.height = "";
    sendBtn.disabled = true;
    addUserBubble(question);
    var loader = showLoader();

    // Snapshot mode flags BEFORE we reset them — caller decides how to
    // route based on these.
    var sendCtx = {
      modifyMode: _modifyMode(),
      rewrite: state.rewrite,
      draft: state.draft,
      scope: state.scope,
      hasAttachment: !!state.attachment,
      selectionText: state.selectionText,
    };

    Promise.resolve(onSend(question, sendCtx)).then(function (result) {
      removeLoader(loader);
      // Reset modify toggles after each AI response (FROM v2 line 7601).
      _resetModifyToggles();
      if (!result) return;
      if (result.action === "replace_text") {
        addActionCard({
          target_original: result.target_original,
          proposed_new: result.proposed_new,
          explanation: result.explanation,
          anchorBookmark: result.anchorBookmark,
        });
      } else if (result.translate) {
        addTranslateBubble(result.translate);
      } else {
        addAiBubble(result.answer || "", result.citations, result.followups, result.hybridNote);
      }
    }).catch(function (err) {
      removeLoader(loader);
      _resetModifyToggles();
      var msg = (err && err.message) || "Unknown error";
      if (/abort|cancel/i.test(msg)) addSystemBubble("⏹️ Request cancelled.");
      else addSystemBubble('❌ Error: <code>' + _esc(msg) + '</code>');
    }).then(function () {
      state.inFlight = false;
      sendBtn.disabled = false;
      inputEl.focus();
    });
  }
  function _resetModifyToggles() {
    state.rewrite = false;
    state.draft = false;
    if (draftChk) draftChk.checked = false;
    var rewriteChk = root.querySelector("#_eli3_chat_rewritechk");
    if (rewriteChk) rewriteChk.checked = false;
    if (pillsEl) { pillsEl.hidden = true; pillsEl.innerHTML = ""; }
    _refreshPlaceholder();
    onModifyModeChange(false);
  }
  sendBtn.onclick = _doSend;

  // Enter sends; Shift+Enter newline. Auto-grow up to manualHeight or
  // 120px (whichever is larger) — manual resize handle (below) lets
  // power users drag for more room. FROM v2 line 7474.
  inputEl.addEventListener("keydown", function (e) {
    if (e.key === "Enter" && !e.shiftKey) { e.preventDefault(); _doSend(); }
  });
  inputEl.addEventListener("input", function () {
    var manual = parseInt(inputEl.dataset.manualHeight || "0", 10) || 0;
    var floor = Math.max(manual, 36);
    inputEl.style.height = "auto";
    inputEl.style.height = Math.max(floor, Math.min(inputEl.scrollHeight, 500)) + "px";
  });

  // ─── Manual resize handle ────────────────────────────────────────
  // FROM v2 line 7456-7472. Dragging the handle adjusts textarea height
  // and stashes the manual floor in dataset.manualHeight so auto-grow
  // respects the user's preferred minimum. Document-level listeners are
  // captured into refs so onBack can remove them — otherwise they leak
  // across pane navigations bound to a closed-over inputEl.
  var resizeHandle = document.createElement("div");
  resizeHandle.className = "_eli3_chat_resize_handle";
  resizeHandle.title = "Drag to resize";
  inputEl.parentNode.insertBefore(resizeHandle, inputEl);
  var resizing = false, startY = 0, startH = 0;
  resizeHandle.addEventListener("mousedown", function (e) {
    resizing = true;
    startY = e.clientY;
    startH = inputEl.offsetHeight;
    document.body.style.cursor = "ns-resize";
    e.preventDefault();
  });
  function _onMouseMove(e) {
    if (!resizing) return;
    var dy = startY - e.clientY;
    var next = Math.max(36, Math.min(500, startH + dy));
    inputEl.style.height = next + "px";
    inputEl.dataset.manualHeight = String(next);
  }
  function _onMouseUp() {
    if (resizing) { resizing = false; document.body.style.cursor = ""; }
  }
  document.addEventListener("mousemove", _onMouseMove);
  document.addEventListener("mouseup", _onMouseUp);
  // Wrap onBack so we tear down listeners + the unsub fires.
  var origOnBack = onBack;
  onBack = function () {
    try { document.removeEventListener("mousemove", _onMouseMove); } catch (e) {}
    try { document.removeEventListener("mouseup", _onMouseUp); } catch (e) {}
    try { origOnBack(); } catch (e) {}
  };
  root.querySelector("._eli3_ae_back").onclick = onBack;

  mount.appendChild(root);

  // Public surface init can call.
  return {
    setSelection: setSelection,
    setAttachment: setAttachment,
    setScope: setScope,
    setDocType: function (label) {
      docTypeLabel = label || "document";
      defaultPlaceholder = "Ask ELI about this " + docTypeLabel + "…";
      _refreshPlaceholder();
    },
    addUserBubble: addUserBubble,
    addAiBubble: addAiBubble,
    addSystemBubble: addSystemBubble,
    addActionCard: addActionCard,
    addTranslateBubble: addTranslateBubble,
    clearScroll: function () { scrollEl.innerHTML = ""; },
    focusInput: function () { inputEl.focus(); },
  };
}

// ─── Attach modal ────────────────────────────────────────────────────
// FROM v2 buildSourceMenuDialog. Two-tab modal: Upload File / Saved
// Templates. Uses showEliDialog as the host. opts.templates is an array
// of {id, label, content, library, category} from the templates store.

view.renderAttachDialog:
function renderAttachDialog(opts) {
  if (typeof showEliDialog !== "function") {
    if (typeof showToast === "function") showToast("Dialog primitive missing", "err");
    return;
  }
  var templates = opts.templates || [];
  var onPickFile = opts.onPickFile || function () {};
  var onPickTemplate = opts.onPickTemplate || function () {};

  function _esc(s) {
    return String(s == null ? "" : s)
      .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;").replace(/'/g, "&#39;");
  }

  // Group templates by library / agreementType.
  var grouped = {};
  templates.forEach(function (t) {
    if (!t || !t.id || String(t.id).charAt(0) === "_") return;
    var lib = t.library || t.category || t.agreementType || "Library";
    if (!grouped[lib]) grouped[lib] = [];
    grouped[lib].push(t);
  });

  // 2026-05-13 follow-up: saved templates COLLAPSED by default to keep
  // the dialog short. Affordance comes from a styled "click-to-expand"
  // summary (chevron + label + count badge + hover state — see
  // style.css `._eli3_chat_attach_group summary`).
  var groupHtml = Object.keys(grouped).sort().map(function (lib) {
    var items = grouped[lib];
    return '<details class="_eli3_chat_attach_group">' +
      '<summary>' +
        '<span class="_eli3_chat_attach_chev" aria-hidden="true">▸</span>' +
        '<span class="_eli3_chat_attach_grouplbl">' + _esc(lib) + '</span>' +
        '<span class="_eli3_chat_attach_count">' + items.length + '</span>' +
        '<span class="_eli3_chat_attach_hint">Click to expand</span>' +
      '</summary>' +
      '<div class="_eli3_chat_attach_items">' +
        items.map(function (t) {
          var name = t.label || t.name || t.id;
          return '<button type="button" class="_eli3_chat_attach_item" data-tpl-id="' + _esc(t.id) + '" title="Click to attach this template">' +
            '<span class="_eli3_chat_attach_item_icon">📄</span>' +
            '<span class="_eli3_chat_attach_item_name">' + _esc(name) + '</span>' +
            '<span class="_eli3_chat_attach_item_action">Attach →</span>' +
          '</button>';
        }).join("") +
      '</div>' +
    '</details>';
  }).join("");

  var bodyHtml =
    '<div class="_eli3_chat_attach_body">' +
      '<div class="_eli3_chat_attach_section">' +
        '<div class="_eli3_chat_attach_secthead">📁 Upload File</div>' +
        '<label class="_eli3_chat_attach_drop" for="_eli3_chat_attach_file">' +
          '<div class="_eli3_chat_attach_drop_icon">📎</div>' +
          '<div class="_eli3_chat_attach_drop_title">Click to choose a file or drop one here</div>' +
          '<div class="_eli3_chat_attach_drop_sub">PDF stays inline · DOCX/TXT extract to text · up to 5 MB</div>' +
        '</label>' +
        '<input type="file" id="_eli3_chat_attach_file" ' +
          'accept=".pdf,application/pdf,' +
                  '.docx,application/vnd.openxmlformats-officedocument.wordprocessingml.document,' +
                  '.txt,text/plain" ' +
          'hidden>' +
      '</div>' +
      (templates.length
        ? '<div class="_eli3_chat_attach_section">' +
            '<div class="_eli3_chat_attach_secthead">📚 Saved Templates</div>' +
            groupHtml +
          '</div>'
        : '<div class="_eli3_chat_attach_section _eli3_chat_attach_empty">No saved templates. Use Build Draft → Templates to add some.</div>') +
    '</div>';

  // ask_dock: when Ask ELI is open inside the dock's slide-down panel
  // (z-index 10001), the kernel's default eli-overlay (z-index 9999) sits
  // BEHIND the panel — modal appears unreachable. Bump above 10002 (the
  // dock handle) so the dialog always sits on top of the dock chrome.
  var _dockOpen = !!document.getElementById("_eli3_askdock_panel");
  showEliDialog({
    variant: "info",
    tier: "premium",
    dialogClass: "_eli3_dialog_wide _eli3_chat_attach_dialog",
    icon: "📎",
    title: "Attach to chat",
    body: bodyHtml,
    zIndex: _dockOpen ? 10500 : undefined,
    secondary: { label: "Cancel" },
    onMount: function (overlay) {
      var fileInp = overlay.querySelector("#_eli3_chat_attach_file");
      if (fileInp) fileInp.onchange = function (e) {
        var f = e.target.files && e.target.files[0];
        if (!f) return;
        onPickFile(f);
        if (overlay.parentNode) overlay.parentNode.removeChild(overlay);
      };
      Array.prototype.forEach.call(overlay.querySelectorAll("[data-tpl-id]"), function (btn) {
        btn.onclick = function () {
          var id = btn.getAttribute("data-tpl-id");
          var t = templates.find(function (tt) { return String(tt.id) === id; });
          if (t) onPickTemplate(t);
          if (overlay.parentNode) overlay.parentNode.removeChild(overlay);
        };
      });
    },
  });
}

// renderDropZoneJumper — FROM v2 showEliDropZoneJumper (line 11726).
// Top-of-pane overlay that asks the user to position their cursor in
// Word, then click "Insert clause" to drop the AI-drafted text at that
// cursor. Used by Draft mode when the AI returns a `replace_text`-style
// action card with NO target_original (pure draft, no clause to replace).

view.renderDropZoneJumper:
function renderDropZoneJumper(opts) {
  var htmlContent = opts.htmlContent || "";
  var mode = opts.mode || "draft";
  var noRedlines = !!opts.noRedlines;
  var onInsert = opts.onInsert || function () {};
  var onCancel = opts.onCancel || function () {};

  var overlay = document.createElement("div");
  overlay.className = "_eli3_chat_dropzone_overlay";
  var msg = (mode === "rewrite")
    ? "Select clause to replace, then click Insert clause."
    : "Place cursor where you want to insert the clause, then click Insert clause.";
  overlay.innerHTML =
    '<div class="_eli3_chat_dropzone_btnrow">' +
      '<button type="button" class="_eli3_chat_dropzone_cancel">Cancel</button>' +
      '<button type="button" class="_eli3_chat_dropzone_insert">⬇️ Insert clause</button>' +
    '</div>' +
    '<div class="_eli3_chat_dropzone_msg">' + msg + '</div>';
  document.body.appendChild(overlay);
  var cancelBtn = overlay.querySelector("._eli3_chat_dropzone_cancel");
  var insertBtn = overlay.querySelector("._eli3_chat_dropzone_insert");
  cancelBtn.onclick = function () {
    if (overlay.parentNode) overlay.parentNode.removeChild(overlay);
    onCancel();
  };
  insertBtn.onclick = function () {
    insertBtn.disabled = true;
    insertBtn.textContent = "Dropping…";
    Promise.resolve(onInsert({ htmlContent: htmlContent, noRedlines: noRedlines })).then(function () {
      if (overlay.parentNode) overlay.parentNode.removeChild(overlay);
    }).catch(function () {
      insertBtn.disabled = false;
      insertBtn.textContent = "Error — try again";
    });
  };
  return {
    close: function () { if (overlay.parentNode) overlay.parentNode.removeChild(overlay); },
  };
}

// ─── Document viewer ─────────────────────────────────────────────────
// Opens an overlay showing the attached document with the best formatting
// we can produce. Routes by attachment kind:
//   - PDF: browser-native viewer in an iframe, jumps to #page=N
//   - DOCX (with html): mammoth-converted HTML rendered in a scrollable
//     panel; cited paragraph is highlighted + scrolled into view
//   - TXT / DOCX (no html): plain text with paragraph breaks, cited
//     paragraph highlighted + scrolled into view
// citation { id: "ATT_5" | "ATT_P3" | "ATT_PDF", text: "..." }
// FROM v3 ask_eli — not in v2; new behavior 2026-05-16.

view.renderDocViewer:
function renderDocViewer(opts) {
  // SELF-CONTAINED: bundler wraps each view fn in `new Function(...)` so
  // sibling-fn refs (like _esc) don't resolve at call time. Inline
  // the helper here. Same rule as engine functions.
  function _esc(s) {
    return String(s == null ? "" : s)
      .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;").replace(/'/g, "&#39;");
  }
  opts = opts || {};
  var attachment = opts.attachment || {};
  var citation = opts.citation || {};
  var onClose = opts.onClose || function () {};
  var name = attachment.name || "Attached document";
  var kind = attachment.kind;
  var citeId = String(citation.id || "");
  var citeText = String(citation.text || "");
  // Parse citation id → { paraIdx?: number, pageNum?: number }
  var paraMatch = citeId.match(/^ATT_(\d+)$/);
  var pageMatch = citeId.match(/^ATT_P(\d+)$/);
  var paraIdx = paraMatch ? parseInt(paraMatch[1], 10) : null;
  var pageNum = pageMatch ? parseInt(pageMatch[1], 10) : null;
  var overlay = document.createElement("div");
  overlay.className = "_eli3_doc_viewer_overlay";
  var bodyHtml = "";
  var pdfBytes = null;
  if (kind === "pdf" && attachment.data) {
    // pdf.js (window.pdfjsLib) must be loaded via Script Lab Libraries tab:
    //   https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.min.js
    // Renders each page to a canvas — works in Office.js sandboxed
    // iframes where data:/blob: PDF URLs are refused.
    try {
      var bin = atob(attachment.data);
      pdfBytes = new Uint8Array(bin.length);
      for (var bi2 = 0; bi2 < bin.length; bi2++) pdfBytes[bi2] = bin.charCodeAt(bi2);
    } catch (e) { pdfBytes = null; }
    if (!pdfBytes) {
      bodyHtml = '<div class="_eli3_doc_viewer_empty">Could not decode PDF for preview.</div>';
    } else if (typeof window.pdfjsLib === "undefined") {
      bodyHtml = '<div class="_eli3_doc_viewer_empty">' +
        '<div style="font-weight:700;margin-bottom:8px;color:#1e293b;">PDF library not loaded</div>' +
        '<div style="font-size:12px;line-height:1.6;">Add this URL to Script Lab\'s <b>Libraries</b> tab and reload:</div>' +
        '<div style="margin-top:8px;padding:8px 10px;background:#1e293b;color:#cbd5e1;font-family:ui-monospace,monospace;font-size:11px;text-align:left;user-select:all;">' +
        'https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.min.js' +
        '</div></div>';
    } else {
      bodyHtml = '<div class="_eli3_doc_viewer_pdf_canvas_host">' +
                 '<div class="_eli3_doc_viewer_pdf_status" id="_eli3_pdfstatus">Reading PDF…</div>' +
                 '<div class="_eli3_doc_viewer_pdf_pages" id="_eli3_pdfpages"></div>' +
                 '</div>';
    }
  } else if (attachment.html) {
    // Mammoth-converted HTML. We wrap paragraphs with ids so we can
    // scroll/highlight by paraIdx. mammoth emits <p>, <h1-6>, <ul>, <ol>.
    // Each top-level block element gets data-att-para-idx; we walk the
    // DOM after insertion to assign these (cleaner than regex).
    bodyHtml = '<div class="_eli3_doc_viewer_html">' + attachment.html + '</div>';
  } else if (attachment.text) {
    // Plain text fallback. Render each paragraph as <p data-att-para-idx="N">.
    var paras = String(attachment.text).split(/\n\s*\n/).map(function (p) {
      return p.replace(/\s+/g, " ").trim();
    }).filter(function (p) { return p.length > 0; });
    if (paras.length === 0) paras = [String(attachment.text)];
    bodyHtml = '<div class="_eli3_doc_viewer_text">' +
      paras.map(function (p, i) {
        return '<p data-att-para-idx="' + (i + 1) + '">' + _esc(p) + '</p>';
      }).join("") +
      '</div>';
  } else {
    bodyHtml = '<div class="_eli3_doc_viewer_empty">No preview available for this attachment.</div>';
  }
  var citeBanner = citeText
    ? '<div class="_eli3_doc_viewer_cite">' +
        '<div class="_eli3_doc_viewer_cite_label">ELI cited from this document:</div>' +
        '<div class="_eli3_doc_viewer_cite_text">' + _esc(citeText.substring(0, 400)) + '</div>' +
      '</div>'
    : "";
  overlay.innerHTML =
    '<div class="_eli3_doc_viewer_card">' +
      '<div class="_eli3_doc_viewer_head">' +
        '<div class="_eli3_doc_viewer_title">📎 ' + _esc(name) + '</div>' +
        '<button class="_eli3_doc_viewer_close" type="button" aria-label="Close">✕</button>' +
      '</div>' +
      citeBanner +
      '<div class="_eli3_doc_viewer_body">' + bodyHtml + '</div>' +
    '</div>';
  document.body.appendChild(overlay);
  var closeBtn = overlay.querySelector("._eli3_doc_viewer_close");
  function close() {
    try { overlay.remove(); } catch (e) {}
    try { onClose(); } catch (e) {}
  }
  if (closeBtn) closeBtn.onclick = close;
  overlay.onclick = function (e) { if (e.target === overlay) close(); };
  // ESC to close
  function escHandler(e) {
    if (e.key === "Escape") { close(); document.removeEventListener("keydown", escHandler); }
  }
  document.addEventListener("keydown", escHandler);
  // For HTML/text bodies, assign para indices + highlight + scroll.
  if (kind !== "pdf") {
    var bodyRoot = overlay.querySelector("._eli3_doc_viewer_body");
    if (bodyRoot) {
      // For mammoth HTML we walk ALL top-level block elements and stamp
      // data-att-para-idx. Match must mirror what init.js _readFile uses
      // to extract paragraphs (doc.body.children, including any blocks
      // with non-empty textContent). For text fallback we already stamped
      // them above. 2026-05-16: filter to blocks with non-empty text —
      // pure-decoration nodes (empty paragraphs, page breaks) shouldn't
      // shift the index. Same filter as init.js.
      var htmlRoot = bodyRoot.querySelector("._eli3_doc_viewer_html");
      if (htmlRoot) {
        var nextIdx = 1;
        for (var bi = 0; bi < htmlRoot.children.length; bi++) {
          var el = htmlRoot.children[bi];
          var t = String(el.textContent || "").replace(/\s+/g, " ").trim();
          if (!t) continue;
          el.setAttribute("data-att-para-idx", String(nextIdx));
          nextIdx++;
        }
      }
      // 2026-05-16: prefer EXACT-TEXT highlight (just the cited words),
      // not block-level. Whole-block highlight bleeds visually when the
      // block is a table, list, or long paragraph. Strategy:
      //   1. Find the target block via paraIdx (preferred) or text search
      //   2. Inside that block, locate the cite text via TreeWalker +
      //      Range API and wrap it in <mark>
      //   3. Scroll the mark into view
      //   4. Block-level fallback only when exact text isn't found inside
      function _highlightTextIn(block, probe) {
        if (!block || !probe) return null;
        var lo = String(probe).toLowerCase().trim();
        if (!lo) return null;
        var bodyText = (block.textContent || "").toLowerCase();
        var startG = bodyText.indexOf(lo);
        // Probe miss → try first ~50 chars only (AI may have paraphrased the tail)
        if (startG === -1 && lo.length > 50) {
          lo = lo.substring(0, 50);
          startG = bodyText.indexOf(lo);
        }
        // Still miss → try last ~50 chars (sometimes the start is boilerplate)
        if (startG === -1) {
          var fullLo = String(probe).toLowerCase().trim();
          if (fullLo.length > 50) {
            lo = fullLo.substring(fullLo.length - 50);
            startG = bodyText.indexOf(lo);
          }
        }
        if (startG === -1) return null;
        var endG = startG + lo.length;
        // Map offsets to text nodes via TreeWalker.
        var walker = document.createTreeWalker(block, NodeFilter.SHOW_TEXT, null, false);
        var cum = 0, sNode = null, sOff = 0, eNode = null, eOff = 0, n;
        while ((n = walker.nextNode())) {
          var len = n.nodeValue.length;
          if (!sNode && cum + len > startG) { sNode = n; sOff = startG - cum; }
          if (cum + len >= endG) { eNode = n; eOff = endG - cum; break; }
          cum += len;
        }
        if (!sNode || !eNode) return null;
        try {
          var range = document.createRange();
          range.setStart(sNode, sOff);
          range.setEnd(eNode, eOff);
          var mark = document.createElement("mark");
          mark.className = "_eli3_doc_viewer_hit_mark";
          try {
            range.surroundContents(mark);
          } catch (e) {
            // Range crosses element boundaries → extract+insert.
            var frag = range.extractContents();
            mark.appendChild(frag);
            range.insertNode(mark);
          }
          return mark;
        } catch (e) {
          return null;
        }
      }
      function _resolveTargetBlock() {
        // Block by paraIdx.
        if (paraIdx != null) {
          var t = bodyRoot.querySelector('[data-att-para-idx="' + paraIdx + '"]');
          if (t) return t;
        }
        // Fall back: search across blocks for first containing probe.
        if (citeText) {
          var probe = citeText.substring(0, 60).toLowerCase().trim();
          var allBlocks = bodyRoot.querySelectorAll("[data-att-para-idx]");
          for (var i = 0; i < allBlocks.length; i++) {
            if ((allBlocks[i].textContent || "").toLowerCase().indexOf(probe) !== -1) {
              return allBlocks[i];
            }
          }
        }
        return null;
      }
      var block = _resolveTargetBlock();
      if (block) {
        var mark = citeText ? _highlightTextIn(block, citeText) : null;
        var scrollTarget = mark || block;
        // If exact text wasn't found inside, fall back to block-level
        // outline (lighter than the old solid fill — just a left border
        // so the user sees the area without the whole block tinted).
        if (!mark) block.classList.add("_eli3_doc_viewer_hit");
        setTimeout(function () {
          try { scrollTarget.scrollIntoView({ behavior: "smooth", block: "center" }); } catch (e) {}
        }, 80);
      }
    }
  }
  // PDF render via pdf.js — assumes window.pdfjsLib is loaded via the
  // Script Lab Libraries tab. workerSrc auto-derived from the loaded
  // pdfjsLib's version if not already set elsewhere.
  if (kind === "pdf" && pdfBytes && typeof window.pdfjsLib !== "undefined") {
    var pdfjsLib = window.pdfjsLib;
    if (pdfjsLib.GlobalWorkerOptions && !pdfjsLib.GlobalWorkerOptions.workerSrc) {
      pdfjsLib.GlobalWorkerOptions.workerSrc =
        "https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js";
    }
    var statusEl = overlay.querySelector("#_eli3_pdfstatus");
    var pagesEl  = overlay.querySelector("#_eli3_pdfpages");
    pdfjsLib.getDocument({ data: pdfBytes }).promise.then(function (pdfDoc) {
      if (statusEl && statusEl.parentNode) statusEl.parentNode.removeChild(statusEl);
      var total = pdfDoc.numPages;
      var renderPromises = [];
      var pageTextLayers = []; // [{ pageIdx, layerEl, wrap }] for post-render search
      for (var pn = 1; pn <= total; pn++) {
        (function (pageIdx) {
          renderPromises.push(pdfDoc.getPage(pageIdx).then(function (page) {
            var SCALE = 1.4;
            var viewport = page.getViewport({ scale: SCALE });
            var canvas = document.createElement("canvas");
            canvas.className = "_eli3_doc_viewer_pdf_page";
            canvas.width = viewport.width;
            canvas.height = viewport.height;
            // Position-relative inner container so text layer can absolutely
            // overlay the canvas pixel-for-pixel.
            var canvasWrap = document.createElement("div");
            canvasWrap.className = "_eli3_doc_viewer_pdf_canvasinner";
            canvasWrap.style.position = "relative";
            canvasWrap.style.width = viewport.width + "px";
            canvasWrap.style.height = viewport.height + "px";
            // pdf.js v3+ requires --scale-factor on the text layer container
            // (or any ancestor) to match viewport.scale. Without it,
            // renderTextLayer throws and the text layer never appears.
            canvasWrap.style.setProperty("--scale-factor", String(SCALE));
            canvasWrap.appendChild(canvas);
            var textLayer = document.createElement("div");
            textLayer.className = "_eli3_pdf_textlayer textLayer";
            textLayer.style.width = viewport.width + "px";
            textLayer.style.height = viewport.height + "px";
            textLayer.style.setProperty("--scale-factor", String(SCALE));
            canvasWrap.appendChild(textLayer);
            var wrap = document.createElement("div");
            wrap.className = "_eli3_doc_viewer_pdf_pagewrap";
            wrap.setAttribute("data-pdf-page", String(pageIdx));
            var label = document.createElement("div");
            label.className = "_eli3_doc_viewer_pdf_pagelabel";
            label.textContent = "Page " + pageIdx + " of " + total;
            wrap.appendChild(label);
            wrap.appendChild(canvasWrap);
            pagesEl.appendChild(wrap);
            // Render canvas + text layer in parallel.
            var canvasRender = page.render({ canvasContext: canvas.getContext("2d"), viewport: viewport }).promise;
            var textRender = page.getTextContent().then(function (textContent) {
              try {
                // pdf.js v3 uses textContentSource; v2 used textContent. Pass
                // both keys — older builds ignore the unknown one.
                var task = pdfjsLib.renderTextLayer({
                  textContentSource: textContent,
                  textContent: textContent,
                  container: textLayer,
                  viewport: viewport,
                  textDivs: [],
                });
                return (task && task.promise) ? task.promise : Promise.resolve();
              } catch (e) {
                return null; // text layer optional; canvas still renders
              }
            }).catch(function () { return null; });
            pageTextLayers.push({ pageIdx: pageIdx, layerEl: textLayer, wrap: wrap });
            return Promise.all([canvasRender, textRender]);
          }));
        })(pn);
      }
      return Promise.all(renderPromises).then(function () {
        // Per-page text search for citation text — highlight matching spans.
        // Sort layers by page order so we land on the earliest match.
        pageTextLayers.sort(function (a, b) { return a.pageIdx - b.pageIdx; });
        var firstHitPage = null;
        if (citeText) {
          var probe = String(citeText).toLowerCase().trim();
          // Try several probe lengths (full, first 60 chars, last 60 chars)
          // so we still match when AI quoted slightly more or less than the
          // verbatim text. Stop at first matching page.
          var probeVariants = [probe];
          if (probe.length > 60) {
            probeVariants.push(probe.substring(0, 60));
            probeVariants.push(probe.substring(probe.length - 60));
          }
          for (var li = 0; li < pageTextLayers.length && !firstHitPage; li++) {
            var layer = pageTextLayers[li];
            var spans = layer.layerEl.querySelectorAll("span");
            if (!spans.length) continue;
            var spanInfo = [];
            var concat = "";
            for (var si = 0; si < spans.length; si++) {
              var t = spans[si].textContent || "";
              spanInfo.push({ span: spans[si], start: concat.length, end: concat.length + t.length });
              concat += t + " "; // space to separate adjacent spans for searchability
            }
            var lo = concat.toLowerCase();
            var matchStart = -1, matchEnd = -1;
            for (var pi = 0; pi < probeVariants.length; pi++) {
              var p = probeVariants[pi];
              if (!p) continue;
              var idx = lo.indexOf(p);
              if (idx !== -1) { matchStart = idx; matchEnd = idx + p.length; break; }
            }
            if (matchStart === -1) continue;
            spanInfo.forEach(function (info) {
              if (info.start < matchEnd && info.end > matchStart) info.span.classList.add("_eli3_pdf_hit");
            });
            firstHitPage = layer;
          }
        }
        // Scroll target priority: text-match page > pageNum citation > nothing
        var scrollWrap = firstHitPage ? firstHitPage.wrap
          : (pageNum ? pagesEl.querySelector('[data-pdf-page="' + pageNum + '"]') : null);
        if (scrollWrap) {
          scrollWrap.classList.add("_eli3_doc_viewer_pdf_hit");
          setTimeout(function () {
            try { scrollWrap.scrollIntoView({ behavior: "smooth", block: "start" }); } catch (e) {}
          }, 80);
        }
      });
    }).catch(function (e) {
      if (statusEl) statusEl.textContent = "PDF render failed: " + (e && e.message || "unknown");
      try {
        if (window.eli && window.eli.log && window.eli.log.event) {
          window.eli.log.event("tool", "ask_eli_pdf_render_failed", { msg: e && e.message });
        }
      } catch (_) {}
    });
  }
  return { close: close };
}

jsonTools.init:
function init(eli) {
  if (!eli.events) eli.events = { guard: function (fn) { return fn; }, safeAsync: function (p) { return p; } };
  var bundle = eli.tools._loaded["ask_eli"];
  if (!bundle) return;
  // ── REDLINE REGEN — kill-switch setting. Default ON; admin can push
  // OFF via admin-overrides.json to disable the feature fleet-wide
  // without redeploying. Registered idempotently; safe to re-init.
  // Remove this block + the REDLINE REGEN sections in view.js + style.css
  // to fully strip the feature.
  try {
    if (eli.settings && typeof eli.settings.register === "function") {
      eli.settings.register("ask_eli_redline_regen_enabled", {
        default: true,
        type: "boolean",
        storage: { type: "ls_blob_field", key: "eli_user_settings", field: "askEliRedlineRegenEnabled" },
        adminPushable: true,
        describe: "Ask ELI: show 'Regen this part' chip when user selects text inside the redline preview of an action card",
      });
    }
  } catch (_e) {}
  // ── END
  var efns = bundle._eliEngineFns || {};
  var vfns = bundle._eliViewFns || {};
  var analyze               = efns.analyze;
  var buildAskEliPrompt     = efns.buildAskEliPrompt;
  var buildTranslatePrompt  = efns.buildTranslatePrompt;
  var buildAttachmentPrefix = efns.buildAttachmentPrefix;
  var capHistory            = efns.capHistory;
  var parseAiResponse       = efns.parseAiResponse;
  var renderCitations       = efns.renderCitations;
  var isTranslateRequest    = efns.isTranslateRequest;
  var cleanDocHtml          = efns.cleanDocHtml;
  var markRedlinesInOoxml   = efns.markRedlinesInOoxml;
  var classifyAuthorsHeuristic = efns.classifyAuthorsHeuristic;
  var computeWordDiff       = efns.computeWordDiff;
  var markdownLite          = efns.markdownLite;
  var renderChat            = vfns.renderChat;
  var renderAttachDialog    = vfns.renderAttachDialog;
  var renderDropZoneJumper  = vfns.renderDropZoneJumper;
  var renderDocViewer       = vfns.renderDocViewer;
  // Updated by showChatInterface on each session start. Used by
  // _onCitationClick to access current ctx.attachment when ATT_<N>
  // citations fire (data attributes can't hold base64 PDF bytes).
  var _liveCtxRef = null;
  if (!analyze || !buildAskEliPrompt || !capHistory || !parseAiResponse || !renderChat) {
    eli.log.event("tool", "ask_eli_load_failed", {
      hasAnalyze: !!analyze, hasBuild: !!buildAskEliPrompt, hasCap: !!capHistory,
      hasParse: !!parseAiResponse, hasView: !!renderChat,
    });
    return;
  }

  // ─── Per-doc chat history — SESSION-SCOPED, in-memory ────────────
  // NOT persisted to IDB (user feedback: carrying chat across reloads is
  // unwanted). It IS held in a module-level store for the current session
  // so the full Ask ELI tile and the ask_dock slide-down panel share ONE
  // conversation per document. Resets on reload. Keyed by docHash so
  // switching documents starts a fresh thread.
  //
  // ask_dock 2026-06-03: these three were no-ops (always []/no-op). Filled
  // to back the shared in-session conversation. REVERT = set _readHistory
  // → Promise.resolve([]), _writeHistory → Promise.resolve(), drop the
  // _sharedSessionHistory line, and remove the delete line in _clearHistory.
  var _sharedSessionHistory = {}; // ask_dock: { docHash: [turns] } — in-memory only
  function _historyKey(docHash) { return "_chat_history_" + (docHash || "default"); }
  function _readHistory(docHash) {
    var h = _sharedSessionHistory[docHash || "default"];
    return Promise.resolve(Array.isArray(h) ? h.slice() : []);
  }
  function _writeHistory(docHash, history) {
    _sharedSessionHistory[docHash || "default"] = Array.isArray(history) ? history.slice() : [];
    return Promise.resolve();
  }
  function _clearHistory(docHash) {
    delete _sharedSessionHistory[docHash || "default"]; // ask_dock: clear shared store
    return eli.events.safeAsync(eli.storage.delete("config", _historyKey(docHash)), "ask_eli.hist_clear").catch(function () {});
  }
  // Sweep legacy persisted history rows. Best-effort; tolerated failure.
  // getAll returns every row in the config store; we filter by id prefix
  // and delete the chat_history ones. Other config rows (oars sentinel,
  // wrongness toggle, etc.) are untouched.
  (function _sweepLegacyHistory() {
    if (!eli.storage || typeof eli.storage.getAll !== "function") return;
    eli.storage.getAll("config").then(function (rows) {
      if (!Array.isArray(rows)) return;
      var stale = rows.filter(function (r) {
        return r && typeof r.key === "string" && r.key.indexOf("_chat_history_") === 0;
      });
      if (!stale.length) return;
      Promise.all(stale.map(function (r) {
        return eli.storage.delete("config", r.key).catch(function () {});
      })).then(function () {
        eli.log.event("tool", "ask_eli_legacy_history_swept", { count: stale.length });
      });
    }).catch(function () { /* tolerate */ });
  })();

  // ─── Doc hash (matches build_draft._bd_hashContent shape) ────────
  function _hashContent(text) {
    if (!text) return "empty";
    var s = String(text), hash = 0;
    for (var i = 0; i < s.length; i++) {
      hash = ((hash << 5) - hash) + s.charCodeAt(i);
      hash |= 0;
    }
    return "h" + (hash >>> 0).toString(36);
  }

  // ─── AskEliAnchor bookmark sweep ─────────────────────────────────
  // FROM v2 line 7138-7150. On chat entry, sweep any prior session's
  // AskEliAnchor_* bookmarks (they render as visible [ ] in Word when
  // "Show bookmarks" is on).
  function _sweepAnchors() {
    if (!eli.host || !eli.host.runRaw) return Promise.resolve();
    return eli.host.runRaw("ask_eli:anchor_sweep", function (context) {
      var bks = context.document.body.getRange().bookmarks;
      bks.load("items");
      return context.sync().then(function () {
        var items = bks.items || [];
        for (var i = 0; i < items.length; i++) {
          var b = items[i];
          if (b && b.name && b.name.indexOf("AskEliAnchor_") === 0) {
            try { b.delete(); } catch (e) {}
          }
        }
        return context.sync();
      });
    }).catch(function () { /* tolerate */ });
  }

  // ─── Doc + selection read ────────────────────────────────────────
  // Loads body.text + body.getOoxml (for redline detection) +
  // selection.text in one runRaw scope. Pricey on big docs (OOXML can
  // be MB-scale on a 50pp contract), so we cache by docText fingerprint.
  // Selection always re-reads (cheap) so chip + prompt context stay live.
  // Cache invalidates on `eli.host.onDocChange` (handler installed by
  // `_wireSelectionUpdates`).
  // FROM v2 line 11410-11418 (Word.run portion of runChatQuery).
  var _docReadCache = null; // { docHash, docText, ooxml, html }
  function _invalidateDocReadCache() { _docReadCache = null; }
  function _readDocAndSelection() {
    // Selection always re-reads (cheap).
    return eli.host.runRaw("ask_eli:read_sel", function (context) {
      var sel = context.document.getSelection();
      sel.load("text");
      return context.sync().then(function () {
        return String((sel && sel.text) || "");
      });
    }).catch(function () { return ""; }).then(function (selText) {
      // If we have a recent doc cache, only re-read body.text to test
      // for an unchanged hash. body.text alone is much cheaper than
      // OOXML+HTML and is the cheapest fingerprint we can build.
      if (_docReadCache) {
        return eli.host.runRaw("ask_eli:read_text_only", function (context) {
          var body = context.document.body;
          body.load("text");
          return context.sync().then(function () { return String(body.text || ""); });
        }).then(function (docText) {
          var hash = _hashContent(docText);
          if (hash === _docReadCache.docHash) {
            return {
              docText: _docReadCache.docText,
              selectionText: selText,
              docHash: _docReadCache.docHash,
              ooxml: _docReadCache.ooxml,
              html: _docReadCache.html,
            };
          }
          // Hash changed — fall through to full read.
          return _doFullDocRead(selText);
        }).catch(function () { return _doFullDocRead(selText); });
      }
      return _doFullDocRead(selText);
    });
  }
  function _doFullDocRead(selText) {
    return eli.host.runRaw("ask_eli:read_doc", function (context) {
      var body = context.document.body;
      body.load("text");
      var ooxmlResult = body.getOoxml();
      var bodyHtml = body.getHtml();
      return context.sync().then(function () {
        return {
          docText: String(body.text || ""),
          ooxml: String((ooxmlResult && ooxmlResult.value) || ""),
          html: String((bodyHtml && bodyHtml.value) || ""),
        };
      });
    }).then(function (raw) {
      var hash = _hashContent(raw.docText);
      _docReadCache = {
        docHash: hash, docText: raw.docText, ooxml: raw.ooxml, html: raw.html,
        cachedAt: Date.now(),
      };
      return {
        docText: raw.docText,
        selectionText: selText || "",
        docHash: hash,
        ooxml: raw.ooxml,
        html: raw.html,
      };
    }).catch(function (err) {
      eli.log.event("tool", "ask_eli_read_failed", { msg: err && err.message, name: err && err.name });
      // Don't poison docHash with "empty" — preserve any prior real hash
      // so history persistence stays stable across transient read failures.
      var fallbackHash = _docReadCache ? _docReadCache.docHash : "empty";
      return { docText: "", selectionText: selText || "", docHash: fallbackHash, ooxml: "", html: "" };
    });
  }
  // Read selection only (cheaper, used by live-update path).
  function _readSelectionOnly() {
    if (!eli.host || !eli.host.runRaw) return Promise.resolve("");
    return eli.host.runRaw("ask_eli:sel_only", function (context) {
      var sel = context.document.getSelection();
      sel.load("text");
      return context.sync().then(function () { return String(sel.text || ""); });
    }).catch(function () { return ""; });
  }

  // ─── Selection live-update wire ──────────────────────────────────
