              var step = Promise.resolve();
              if (redlinesOn) {
                if (oldStr) {
                  step = step.then(function () {
                    return _ensureMode("Off").then(function () {
                      var delRange = currentCursor.insertText(oldStr + sp, "After");
                      pendingFmt.push({ range: delRange, fmt: ofmt });
                      // Flip to TrackAll — _flush() inside _ensureMode runs
                      // first, so delRange is formatted BEFORE the tracked
                      // deletion. Sync after the replace so the deletion is
                      // settled before any same-mode insert that follows.
                      return _ensureMode("TrackAll").then(function () {
                        delRange.insertText("", "Replace");
                        currentCursor = delRange;
                        return context.sync();
                      });
                    });
                  });
                }
                if (newStr) {
                  step = step.then(function () {
                    return _ensureMode("TrackAll").then(function () {
                      var insRange = currentCursor.insertText(newStr + sp, "After");
                      currentCursor = insRange;
                      pendingFmt.push({ range: insRange, fmt: ofmt });
                    });
                  });
                }
              } else {
                if (newStr) {
                  step = step.then(function () {
                    return _ensureMode("Off").then(function () {
                      var insRange = currentCursor.insertText(newStr + sp, "After");
                      currentCursor = insRange;
                      pendingFmt.push({ range: insRange, fmt: ofmt });
                    });
                  });
                }
              }
              return step;
            });
          });
          // Final flush — format the last run of inserts.
          return p.then(function () { return _flush(); });
        });
      });
    });
  }

  // FROM v2 applyFmt (line 22963) — verbatim except: when underline is
  // unrecognized, SKIP the property instead of forcing "None". v2's
  // else-branch wiped underline on Word-for-Web's enum values; this
  // change keeps underline that's already there from a prior emit.
  function _applyFmt(range, fmt) {
    if (!fmt || !range) return;
    var validUnderlines = [
      "None","Single","Words","Double","Thick","Dotted","DottedHeavy",
      "DashLine","DashLineHeavy","DashLineLong","DashLineLongHeavy",
      "DotDashLine","DotDashLineHeavy","TwoDotDashLine","TwoDotDashLineHeavy",
      "Wave","WaveHeavy","WaveDouble",
    ];
    function _try(setter) { try { setter(); } catch (e) { /* tolerate */ } }
    if (typeof fmt.bold === "boolean")   _try(function () { range.font.bold = fmt.bold; });
    if (typeof fmt.italic === "boolean") _try(function () { range.font.italic = fmt.italic; });
    if (typeof fmt.size === "number")    _try(function () { range.font.size = fmt.size; });
    if (typeof fmt.name === "string" && fmt.name)
      _try(function () { range.font.name = fmt.name; });
    if (typeof fmt.underline === "string" && validUnderlines.indexOf(fmt.underline) !== -1) {
      _try(function () { range.font.underline = fmt.underline; });
    }
    // else: skip (don't wipe to "None"). v2 wiped here; that bug killed
    // underline whenever Word returned a non-string enum value.
  }

  // ─── File reader (PDF / DOCX / TXT) ──────────────────────────────
  // FROM v2 chatCustomFileInput.onchange. PDF → base64 + inlineData.
  // DOCX → mammoth.extractRawText (if mammoth global is loaded).
  // TXT → TextDecoder.
  function _readFile(file) {
    return new Promise(function (resolve, reject) {
      var name = String(file.name || "attachment");
      var lower = name.toLowerCase();
      var reader = new FileReader();
      reader.onerror = function () { reject(new Error("Failed to read file")); };
      if (/\.pdf$/.test(lower)) {
        reader.onload = function () {
          var b64 = reader.result.split(",")[1];
          resolve({ kind: "pdf", name: name, mime: "application/pdf", data: b64 });
        };
        reader.readAsDataURL(file);
      } else if (/\.docx$/.test(lower)) {
        reader.onload = function () {
          if (typeof window.mammoth === "undefined" || !window.mammoth.extractRawText) {
            reject(new Error("Mammoth library not loaded — can't extract DOCX text."));
            return;
          }
          // 2026-05-16: also call convertToHtml so the document viewer
          // can render the attached docx with formatting (headings, bold,
          // lists) instead of plain text. Both come from the same
          // arrayBuffer in parallel. text → prompt; html → viewer.
          var buf = reader.result;
          var textPromise = window.mammoth.extractRawText({ arrayBuffer: buf })
            .then(function (res) { return String(res.value || ""); });
          var htmlPromise = window.mammoth.convertToHtml
            ? window.mammoth.convertToHtml({ arrayBuffer: buf })
                .then(function (res) { return String(res.value || ""); })
                .catch(function () { return ""; }) // viewer falls back to text if convertToHtml fails
            : Promise.resolve("");
          Promise.all([textPromise, htmlPromise])
            .then(function (out) {
              var text = out[0], html = out[1];
              // 2026-05-16: extract per-block paragraphs from the mammoth HTML
              // so the prompt's ATT_<N> index lines up with the viewer's block
              // enumeration. Without this, the prompt splits raw text on blank
              // lines (which doesn't match HTML block boundaries — headings
              // and lists especially diverge) → AI cites ATT_5 meaning the
              // 5th raw-text paragraph but the viewer scrolls to the 5th
              // HTML block, a different element. Pulling paragraphs from
              // the HTML once at attach time guarantees they agree.
              var paragraphs = [];
              if (html && typeof window.DOMParser !== "undefined") {
                try {
                  var doc = new window.DOMParser().parseFromString(html, "text/html");
                  var kids = doc && doc.body ? doc.body.children : [];
                  for (var i = 0; i < kids.length; i++) {
                    var t = String(kids[i].textContent || "").replace(/\s+/g, " ").trim();
                    if (t) paragraphs.push(t);
                  }
                } catch (_) { /* fall back to raw-text splitting */ }
              }
              resolve({ kind: "file", name: name, text: text, html: html, paragraphs: paragraphs });
            })
            .catch(function (e) { reject(new Error("DOCX parse failed: " + (e && e.message || "unknown"))); });
        };
        reader.readAsArrayBuffer(file);
      } else if (/\.(txt|csv|json|md)$/.test(lower)) {
        reader.onload = function () {
          var text;
          try { text = new TextDecoder("utf-8").decode(reader.result); }
          catch (e) { text = String(reader.result || ""); }
          resolve({ kind: "file", name: name, text: text, html: "" });
        };
        reader.readAsArrayBuffer(file);
      } else {
        reject(new Error("Unsupported file type. Use PDF, DOCX, or TXT."));
      }
    });
  }

  // ─── Activity feed: per-conversation entry mutation ──────────────
  // FROM v2 _updateAskEliActivity (line 11206). First call creates a
  // fresh activity entry + caches its id on `state.activityId`. Each
  // subsequent call MUTATES the same entry via `eli.activity.update`
  // (kernel API, added 2026-05-10). Failure path falls back to a new
  // entry per turn.
  function _updateActivity(state, question, answerHtml, citations, opts) {
    if (!eli.activity || !eli.activity.add) return;
    opts = opts || {};
    var turn = { question: question, answer: answerHtml, citations: citations || [], at: Date.now() };
    state.activityTurns = (state.activityTurns || []).concat([turn]);
    var summary = state.activityTurns.length + " message" + (state.activityTurns.length === 1 ? "" : "s") +
      " · " + String(question).substring(0, 80);
    var icon = opts.icon || "🤖";
    var label = opts.label || "Ask ELI";

    // First turn — create entry, stash its id. restoreChannel/Key are
    // the kernel-spec hooks that make a feed item clickable; clicking
    // dispatches to ask_eli's activity_restore handler which re-opens
    // the chat with replayTurns.
    if (!state.activityId) {
      var entry = eli.activity.add({
        type: "ask-eli",
        icon: icon,
        label: label,
        summary: summary,
        payload: {
          turns: state.activityTurns,
          docHash: state.docHash,
        },
        provenance: { timestamp: Date.now() },
        restoreChannel: "activity_restore",
        restoreKey: "ask-eli",
      });
      state.activityId = entry && entry.id;
      return;
    }

    // Subsequent turns — mutate the same entry.
    if (typeof eli.activity.update === "function") {
      var ok;
      try {
        ok = eli.activity.update(state.activityId, {
          summary: summary,
          payload: {
            turns: state.activityTurns,
            docHash: state.docHash,
          },
          // Refresh icon/label in case translate-mode changed them mid-session.
          icon: icon,
          label: label,
          restoreChannel: "activity_restore",
          restoreKey: "ask-eli",
        });
      } catch (e) {
        // ValidationError on patch — log + fall through to append.
        eli.log.event("tool", "ask_eli_activity_update_failed", { msg: e && e.message });
        ok = null;
      }
      if (ok) return;
      // Update returned null OR threw — id not found (rotated out of ring)
      // OR the patch was invalid. Verify the entry is genuinely gone from
      // the ring before appending a fresh one — otherwise we'd fork the
      // conversation (two ask-eli rows with overlapping turn lists).
      if (typeof eli.activity.list === "function") {
        try {
          var ringEntries = eli.activity.list({ includeInternal: true }) || [];
          var stillThere = ringEntries.some(function (e) { return e && e.id === state.activityId; });
          if (stillThere) {
            // Update failed for a non-rotation reason (patch validation).
            // Don't fork — drop this turn from activity feed; logs already
            // captured the failure. Next turn will retry update.
            return;
          }
        } catch (e) { /* tolerate — fall through to append */ }
      }
      state.activityId = null;
    }
    // Genuine fallback path: kernel lacks update OR id confirmed rotated.
    var fallback = eli.activity.add({
      type: "ask-eli", icon: icon, label: label, summary: summary,
      payload: { turns: state.activityTurns, docHash: state.docHash },
      provenance: { timestamp: Date.now() },
      restoreChannel: "activity_restore",
      restoreKey: "ask-eli",
    });
    state.activityId = fallback && fallback.id;
  }

  // ─── Action card Apply ────────────────────────────────────────────
  // FROM v2 renderActionCard apply path (line 11637-11713). Three paths:
  //  - target_original empty + proposed text → drop-zone jumper (pure Draft)
  //  - useRedlines + computeWordDiff loaded → highlight + confirm + surgical
  //  - else → block-level insertHtml with TrackAll/Off
  function _applyAction(payload) {
    var target = String(payload.target_original || "").trim();
    var proposed = String(payload.proposed_new || "");
    var anchor = payload.anchorBookmark;
    var useRedlines = !!payload.useRedlines;
    if (!proposed) return Promise.reject(new Error("Missing proposed text"));

    // Pure Draft path — no target to replace. Show drop-zone jumper so
    // user positions cursor and clicks Insert. FROM v2 line 11628.
    if (!target && renderDropZoneJumper) {
      return new Promise(function (resolve, reject) {
        renderDropZoneJumper({
          htmlContent: proposed,
          mode: "draft",
          noRedlines: !useRedlines,
          onInsert: function (opts) {
            return eli.host.runRaw("ask_eli:dropzone_insert", function (context) {
              try {
                context.document.changeTrackingMode = opts.noRedlines
                  ? Word.ChangeTrackingMode.off
                  : Word.ChangeTrackingMode.trackAll;
              } catch (e) {}
              var sel = context.document.getSelection();
              sel.insertHtml(opts.htmlContent, "Replace");
              return context.sync();
            }).then(function () {
              resolve({ message: "✓ Inserted at cursor" });
            }).catch(reject);
          },
          onCancel: function () { reject(new Error("Cancelled")); },
        });
      });
    }

    // Surgical path runs whenever target + diff are available. Honors
    // `useRedlines` (the action-card Redlines ON/OFF toggle): ON emits
    // track-changes marks, OFF emits the rewrite cleanly with the same
    // per-word format snapshot. Matches legal_risks rewrite editor.
    // Confirmation flow: select the target in Word so user sees what's
    // about to change, then eli.ui.confirm. On miss, bail with a toast —
    // better to refuse than to overwrite the wrong paragraph.
    if (target && _surgicalRedlineApply && computeWordDiff) {
      return _highlightTargetInDoc(target, anchor).then(function (located) {
        if (!located) {
          if (typeof showToast === "function") {
            showToast("Couldn't locate the target text in the document", "err");
          }
          throw new Error("Target text not found");
        }
        return eli.ui.confirm({
          title: "Apply replacement?",
          message: useRedlines
            ? "The text to be replaced is now highlighted in your document. Apply the proposed change with track changes?"
            : "The text to be replaced is now highlighted in your document. Apply the proposed change CLEAN (no track changes)?",
          confirmLabel: "Apply",
          cancelLabel: "Cancel",
          variant: "info",
        });
      }).then(function (ok) {
        if (!ok) throw new Error("Cancelled");
        return _surgicalRedlineApply(target, target, proposed, anchor, useRedlines)
          .then(function (res) {
            if (anchor) _deleteAnchor(anchor);
            if (res && res.noop) {
              return { message: "✓ No changes — proposed matches target" };
            }
            return { message: useRedlines
              ? "✓ Applied with surgical track changes"
              : "✓ Applied (clean, formatting preserved)" };
          })
          .catch(function (err) {
            eli.log.event("tool", "ask_eli_surgical_failed", {
              msg: err && err.message, name: err && err.name,
            });
            if (typeof showToast === "function") {
              showToast("Surgical apply failed — falling back to block replace.", "warn");
            }
            return _applyActionBlock(target, proposed, anchor, useRedlines);
          });
      });
    }

    // Block-level fallback path (original implementation).
    return _applyActionBlock(target, proposed, anchor, useRedlines);
  }

  // Highlight the target text in the document so the user can visually
  // confirm before committing to a redline. Resolves true on a successful
  // selection (anchor or search hit), false otherwise. Doesn't modify
  // the document — purely a `select() + scrollIntoView()` call.
  function _highlightTargetInDoc(target, anchor) {
    if (!target || !eli.host || !eli.host.runRaw) return Promise.resolve(false);
    return eli.host.runRaw("ask_eli:highlight_target", function (context) {
      var doc = context.document;
      var bookmarkProxy = null;
      if (anchor) {
        try {
          var b = doc.body.getRange().bookmarks.getItemOrNullObject(anchor);
          b.load("isNullObject");
          bookmarkProxy = b;
        } catch (e) { /* tolerate */ }
      }
      // Word.search caps at 255 chars. For targets longer than the head
      // window we'd otherwise highlight only the first ~3 lines. Find
      // the head (first 250) AND the tail (last 200), then expand the
      // head match to the tail match's end so the full clause is selected.
      var full = String(target);
      var head = full.substring(0, 250).trim();
      var hasTail = full.length > 250;
      var tail = hasTail ? full.substring(full.length - 200).trim() : "";
      var headRes = doc.body.search(head, {
        matchCase: false, matchWholeWord: false, ignorePunct: true, ignoreSpace: true,
      });
      headRes.load("items");
      return context.sync().then(function () {
        var range = null;
        var usedBookmark = false;
        if (bookmarkProxy && !bookmarkProxy.isNullObject) {
          range = bookmarkProxy.getRange();
          usedBookmark = true;
        } else if (headRes.items && headRes.items.length) {
          range = headRes.items[0];
        }
        if (!range) return false;
        // Bookmark already covers the full clause; short targets fit in head.
        if (usedBookmark || !hasTail) {
          try { range.select(); range.scrollIntoView(); } catch (e) {}
          return context.sync().then(function () { return true; });
        }
        // Long target, search-fallback path: extend head match to tail.
        var afterHead = range.getRange("Start").expandTo(doc.body.getRange("End"));
        var tailRes = afterHead.search(tail, {
          matchCase: false, matchWholeWord: false, ignorePunct: true, ignoreSpace: true,
        });
        tailRes.load("items");
        return context.sync().then(function () {
          var picked = range;
          if (tailRes.items && tailRes.items.length) {
            var candidate = range.getRange("Start").expandTo(tailRes.items[0].getRange("End"));
            candidate.load("text");
            return context.sync().then(function () {
              // Reject runaway expansion (tail matched in a later section).
              if (candidate.text && candidate.text.length < full.length + 1500) {
                picked = candidate;
              }
              try { picked.select(); picked.scrollIntoView(); } catch (e) {}
              return context.sync().then(function () { return true; });
            });
          }
          try { picked.select(); picked.scrollIntoView(); } catch (e) {}
          return context.sync().then(function () { return true; });
        });
      });
    }).catch(function () { return false; });
  }

  // Block-level Apply — replaces the whole target range with proposed.
  function _applyActionBlock(target, proposed, anchor, useRedlines) {
    if (!target) return Promise.reject(new Error("Missing target text"));
    return eli.host.runRaw("ask_eli:apply_action", function (context) {
      var doc = context.document;
      // Try anchor first — capture the bookmark proxy so we can resolve
      // it after sync. (Renamed from `range` to `bookmarkProxy` so it
      // doesn't shadow the resolved Range below.)
      var bookmarkProxy = null;
      if (anchor) {
        try {
          var b = doc.body.getRange().bookmarks.getItemOrNullObject(anchor);
          b.load("isNullObject");
          bookmarkProxy = b;
        } catch (e) { /* fall through to search */ }
      }
      // Search fallback (Word.search has a 255-char query limit — the
      // returned range is just the matched substring, not the full clause.
      // Below we expand it to the full paragraph so the WHOLE clause gets
      // replaced when there's no anchor available).
      var searchRes = doc.body.search(target.substring(0, 250), {
        matchCase: false, matchWholeWord: false, ignorePunct: true, ignoreSpace: true,
      });
      searchRes.load("items");
      return context.sync().then(function () {
        var actualRange = null;
        var fromSearch = false;
        if (bookmarkProxy && !bookmarkProxy.isNullObject) {
          actualRange = bookmarkProxy.getRange();
          actualRange.load("text");
        } else if (searchRes.items && searchRes.items.length > 0) {
          actualRange = searchRes.items[0];
          fromSearch = true;
        }
        if (!actualRange) {
          throw new Error("Couldn't locate target text in document");
        }
        // When we fell back to search AND the target was longer than
        // Word.search's 255-char query limit, the search query was
        // truncated to the first 250 chars — meaning the found range
        // only covers that prefix, not the full target. Expand to the
        // paragraph in that case so the WHOLE clause gets replaced.
        //
        // But if the target FITS within 250 chars (one sentence, short
        // phrase, sub-clause), the search match IS the full target —
        // expanding to the paragraph would OVER-REPLACE (e.g., user
        // selected one sentence and the whole paragraph gets blown
        // away). Only expand when the search was actually truncated.
        if (fromSearch && target.length > 250) {
          try {
            actualRange = actualRange.paragraphs.getFirst().getRange();
          } catch (e) { /* keep narrow range if paragraph access fails */ }
        }
        if (useRedlines) {
          // Track-changes path — insertHtml is fine. Redline marks visualize
          // every word swap and the user reviews via Word's UI.
          try {
            context.document.changeTrackingMode = Word.ChangeTrackingMode.trackAll;
          } catch (e) {}
          actualRange.insertHtml(proposed, "Replace");
          return context.sync().then(_cleanupAnchor);
        }
        // Clean-apply path — preserve the doc's font with a snapshot +
        // insertText. insertHtml was inserting in HTML default fonts
        // (Calibri / Times New Roman 11) regardless of the doc's actual
        // paragraph font; insertText inherits typography from the
        // existing range automatically, and the snapshot restores
        // bold/italic/underline that the AI's plain-text payload would
        // otherwise drop.
        var textRanges = actualRange.getTextRanges([" ", "\r", "\n", "\t", "\xA0"], false);
        textRanges.load("items/text, items/font/bold, items/font/italic, items/font/underline, items/font/size, items/font/name");
        return context.sync().then(function () {
          var snap = null;
          for (var ri = 0; ri < (textRanges.items || []).length; ri++) {
            var tr = textRanges.items[ri];
            if (tr.text && tr.text.trim()) {
              snap = _aeSrCaptureSnap(tr.font);
              break;
            }
          }
          try {
            context.document.changeTrackingMode = Word.ChangeTrackingMode.off;
          } catch (e) {}
          var newRange = actualRange.insertText(proposed, "Replace");
          if (snap) _aeSrApplySnap(newRange, snap);
          return context.sync().then(_cleanupAnchor);
        });
        function _cleanupAnchor() {
          if (!anchor) return null;
          var bks = doc.body.getRange().bookmarks;
          bks.load("items");
          return context.sync().then(function () {
            for (var i = 0; i < bks.items.length; i++) {
              if (bks.items[i].name === anchor) {
                try { bks.items[i].delete(); } catch (e) {}
              }
            }
            return context.sync();
          });
        }
      });
    }).then(function () {
      return { message: useRedlines ? "✓ Applied with track changes" : "✓ Applied (clean, formatting preserved)" };
    });
  }

  // ─── Improve-prompt helper ───────────────────────────────────────
  // FROM v2 improveBtn (line 7530+). Quick AI rewrite of the user's draft
  // question to be more precise/specific. Uses prompt key "improvePrompt"
  // if loaded; otherwise inline.
  function _improvePrompt(current) {
    if (!eli.ai || !eli.ai.complete) return Promise.resolve(current);
    var prompt = "Improve the following question to be more precise, specific, and useful when asked about a legal document. " +
      "Return ONLY the improved question — no preamble, no quotes, no explanation.\n\nORIGINAL: " + current;
    return Promise.resolve(eli.ai.complete(prompt, { sanitize: false })).then(function (out) {
      var s = String(out || "").trim().replace(/^[`"']|[`"']$/g, "");
      return s || current;
    }).catch(function () { return current; });
  }

  // ─── Doc-type label ──────────────────────────────────────────────
  // 2026-06-09: always "document". The kernel's keyword heuristic
  // (window._eliDocType) misfires often enough that a confident wrong
  // label ("Ask ELI about this Material Transfer Agreement" on an MSA)
  // erodes trust — generic beats wrong. The AI prompt context still
  // receives the detected type separately; this is display-only.
  function _detectDocTypeLabel() {
    return "document";
  }

  // ─── Open the chat ───────────────────────────────────────────────
  // Header index-status dot: "busy" (amber pulse) while the paragraph
  // index warms in the background, "ready" (green) once it's cached so
  // questions are fast. Tolerates the element not existing yet — the
  // chat shell renders a moment after _open fires the warm-up.
  function _setIdxDot(state) {
    try {
      var d = document.getElementById("_eli3_ae_idxdot");
      if (!d) return;
      d.className = "_eli3_ae_idxdot _eli3_ae_idxdot_" + state;
      d.title = state === "ready" ? "Document indexed — answers will be fast"
        : state === "busy" ? "Indexing the document…"
        : "Index builds on your first question";
    } catch (_) {}
  }

  function _open(preloadOpts) {
    preloadOpts = preloadOpts || {};
    if (!eli.ai || !eli.ai.hasApiKey()) {
      if (typeof showToast === "function") showToast("Set a Gemini API key in Settings → Global first.", "warn");
      if (eli.settings && eli.settings.show) eli.settings.show();
      return;
    }
    // ask_dock: in panel mode the underlying tool owns the FSM — don't transition.
    if (!preloadOpts.panelMode) { try { eli.fsm.transition("rendering"); } catch (e) {} }
    // ask_dock: allow a mount override (the dock renders into its slide-down panel).
    var mount = preloadOpts.mount || document.getElementById("_eli3_dashboard_root");

    var welcomeName = "there";
    try {
      var ident = eli.tools && eli.tools.userIdentity ? eli.tools.userIdentity() : null;
      if (ident && (ident.firstName || ident.name)) {
        welcomeName = ident.firstName || (ident.name || "").split(/\s+/)[0] || "there";
      }
    } catch (e) {}

    // Mutable per-session state.
    var ctx = {
      docText: "", selectionText: "", docHash: "empty",
      history: [],
      attachment: null,           // { kind:"pdf"|"file"|"template", name, text?, html?, mime?, data? }
      activeTemplatePayload: null,
      scope: "attached",          // "attached" | "both"
      modifyMode: false,
      activityTurns: [],
      currentAnchor: null,
      unsubSelection: null,
      view: null,
    };
    // 2026-05-16: module-level ref so _onCitationClick can read the
    // current attachment when an ATT_ citation is clicked (chip data
    // attributes can't hold base64 PDF bytes). Single chat session at
    // a time → safe to overwrite on each renderChat call.
    _liveCtxRef = ctx;

    // Speed: render the chat shell IMMEDIATELY (don't wait for the
    // sweep/OOXML/history triple-await — that was ~500-800ms on big
    // docs and caused a visible delay between speech-bubble click and
    // chat appearing). Anchor sweep is non-critical maintenance →
    // fire-and-forget. Full doc/selection read happens in parallel
    // with the render; by the time the user types their first message
    // the heavy OOXML/HTML cache is populated. If the user hits Send
    // before the cache lands, _runQuery awaits ctx.docText anyway.
